class CbtsMapper(object):
    """ It allows to access testline instance variable directly using new name.
    It's main purpose is to create one more abstraction layer to change
    variable references without touching CbtsModel.
    """

    def __init__(self, heat):
        self.__mappings = {
            'oam_ip': 'bts.oam_ip',
            'vnf_name': 'bts.vnf_name'
        }

        self.separator = '.'
        self._heat = heat

    def get_value(self, attribute):
        """ Returns variable from heat accordingly to defined mapping.
        If attribute does not exist, then None will be returned.

        :attribute: str which should be defined in mappings as key"""
        obj, attr_name = self.get_mapping(attribute)
        try:
            val = getattr(obj, attr_name)
        except (AttributeError, KeyError):
            val = None
        return val

    def set_value(self, attribute, value):
        """ Set heat variable accordingly to defined mapping.

        :attribute: str which should be defined in mappings as key
        :value: new value to set
        """
        obj, attr_name = self.get_mapping(attribute)
        return setattr(obj, attr_name, value)

    def get_mapping(self, attribute):
        """ Returns tuple (mapped object, attribute name), where mapped object
        is an instance of model from taf.config.testline and attribute name is
        variable name of this instance.

        :attribute: str which should be defined in mappings as key
        """
        mapped_name = self.__mappings[attribute]
        stack_name, stack_attr_name = mapped_name.split(self.separator)
        stack_obj = getattr(self._heat, stack_name)
        return stack_obj, stack_attr_name
